window.CARD_DATA_URIS = {"black.png": "data:image/webp;base64,", "blue.png": "data:image/webp;base64,", "brick-icon.png": "data:image/webp;base64,", "brick.png": "data:image/webp;base64,", "camera.png": "data:image/webp;base64,", "city.png": "data:image/webp;base64,", "defeat.png": "data:image/webp;base64,", "development-icon.png": "data:image/webp;base64,", "dice-icon.png": "data:image/webp;base64,", "green.png": "data:image/webp;base64,", "house.png": "data:image/webp;base64,", "knight.png": "data:image/webp;base64,", "largestarmy.png": "data:image/webp;base64,", "longestroad.png": "data:image/webp;base64,", "monopoly.png": "data:image/webp;base64,", "orange.png": "data:image/webp;base64,", "purple.png": "data:image/webp;base64,", "red.png": "data:image/webp;base64,", "resource_sale.png": "data:image/webp;base64,", "road.png": "data:image/webp;base64,", "road_building.png": "data:image/webp;base64,", "sandclock-icon.png": "data:image/webp;base64,", "sheep-icon.png": "data:image/webp;base64,", "sheep.png": "data:image/webp;base64,", "skip-icon.png": "data:image/webp;base64,", "stone-icon.png": "data:image/webp;base64,", "stone.png": "data:image/webp;base64,", "thebearcatan.png": "data:image/webp;base64,", "thief.png": "data:image/webp;base64,", "trade.png": "data:image/webp;base64,", "victory.png": "data:image/webp;base64,", "victory_point.png": "data:image/webp;base64,", "wheat-icon.png": "data:image/webp;base64,", "wheat.png": "data:image/webp;base64,", "wood-icon.png": "data:image/webp;base64,", "wood.png": "data:image/webp;base64,", "help.png": "data:image/webp;base64,", "startingbackground.png": "data:image/webp;base64,"};

// Aliases registration for instant key lookup
(function() {
    if (!window.CARD_DATA_URIS) window.CARD_DATA_URIS = {};
    const u = window.CARD_DATA_URIS;
    const keys = Object.keys(u);
    for (let i = 0; i < keys.length; i++) {
        const k = keys[i];
        const val = u[k];
        if (!k.startsWith('images/')) u['images/' + k] = val;
        if (!k.startsWith('./images/')) u['./images/' + k] = val;
        const noExt = k.replace(/\.[a-zA-Z0-9]+$/, '').replace(/^(\.\/)?images\//, '');
        u[noExt] = val;
        u['images/' + noExt] = val;
    }
    if (u['stone.png']) {
        u['ore'] = u['stone.png'];
        u['ore.png'] = u['stone.png'];
        u['images/ore.png'] = u['stone.png'];
        u['images/stone.png'] = u['stone.png'];
    }
    if (u['stone-icon.png']) {
        u['ore-icon'] = u['stone-icon.png'];
        u['ore-icon.png'] = u['stone-icon.png'];
        u['images/ore-icon.png'] = u['stone-icon.png'];
    }
    if (u['victory_point.png']) {
        u['dev'] = u['victory_point.png'];
        u['dev.png'] = u['victory_point.png'];
        u['images/dev.png'] = u['victory_point.png'];
    }
})();
